// The one-step decay factor, generated by exact integer arithmetic.
// D-139: the scoring period is one UTC calendar day; the half-life dial is
// a DURATION and arrives as fixture data (halfLifeDays), never hardcoded here.

import { test } from "node:test";
import assert from "node:assert/strict";

import { decayOneDay, oneDayDecayFp } from "../src/decay.ts";
import { FP_SCALE } from "../src/standard_multiplier.ts";

test("anchors: half-life 1 and 2", () => {
  // 2^(-1/1) = 0.5 exactly; 2^(-1/2) = 1/sqrt(2) -> floor 707106781.
  assert.equal(oneDayDecayFp(1n), 500_000_000n);
  assert.equal(oneDayDecayFp(2n), 707_106_781n);
});

test("defining property: largest v with v^H * 2 <= (1e9)^H", () => {
  for (const H of [1n, 2n, 13n, 26n, 52n]) {
    const v = oneDayDecayFp(H);
    const target = FP_SCALE ** H;
    assert.ok(v ** H * 2n <= target, `H=${H}: v too large`);
    assert.ok((v + 1n) ** H * 2n > target, `H=${H}: v not maximal`);
  }
});

test("monotone in the half-life dial", () => {
  let prev = 0n;
  for (const H of [1n, 2n, 4n, 8n, 16n, 26n, 52n, 104n]) {
    const v = oneDayDecayFp(H);
    assert.ok(v > prev, `H=${H} not strictly above H smaller`);
    assert.ok(v < FP_SCALE);
    prev = v;
  }
});

test("half-life property on a running total: H steps roughly halve, floored", () => {
  const H = 182n;
  const d = oneDayDecayFp(H);
  let total = 1_000_000_000_000n; // 1000 alpha, in rao
  for (let i = 0n; i < H; i++) total = decayOneDay(total, d);
  // Floor-only rounding means the result sits at or just below one half.
  assert.ok(total <= 500_000_000_000n);
  assert.ok(total > 499_990_000_000n);
});

test("rejects a zero half-life", () => {
  assert.throws(() => oneDayDecayFp(0n));
});
